-- Apply to the Supabase database used by the next-generation environment
-- BEFORE deploying the updated scoring cell Netlify functions.
ALTER TABLE public.scoring_cells
  ADD COLUMN IF NOT EXISTS is_reviewed boolean NOT NULL DEFAULT false;

-- Existing correctly scored cells were necessarily reviewed.
UPDATE public.scoring_cells
SET is_reviewed = true
WHERE is_correct = true AND is_reviewed = false;

-- Do not infer review from legacy is_correct=false rows: those may have been
-- generated by the obsolete row-wide 'passed' mechanism.
